    check(page.evaluate('__XENOFIELD__.store.palettes[__XENOFIELD__.store.settings.lutSlot][34]')=='000000' and page.evaluate('__XENOFIELD__.store.palettes[__XENOFIELD__.store.settings.lutSlot][51]')=='FFFFFF','LUT diagonal gradient spans colour A to B across the selected region')
    page.locator('#lutToolBrush').click();page.locator('#lutBrushShape').select_option('irregular');page.locator('#lutBrushSize').fill('3');c85=page.locator('#lutGrid .lut-cell').nth(85).bounding_box();page.mouse.click(c85['x']+c85['width']/2,c85['y']+c85['height']/2);page.wait_for_timeout(20)
    check(page.locator('#lutGrid .lut-cell.selected').count()>1,'Irregular LUT brush paints a multi-cell irregular footprint')
    page.locator('#lutToolSelect').click();c0=page.locator('#lutGrid .lut-cell').nth(0).bounding_box();page.mouse.click(c0['x']+c0['width']/2,c0['y']+c0['height']/2);page.locator('#lutSelectNone').click();page.evaluate("()=>{const dt=new DataTransfer();dt.setData('text/plain','112233 445566\\n778899 AABBCC');document.getElementById('lut').dispatchEvent(new ClipboardEvent('paste',{clipboardData:dt,bubbles:true,cancelable:true}));}");page.wait_for_timeout(20)
