    check(page.evaluate("document.getElementById('previewWrap').compareDocumentPosition(document.querySelector('#skysynth .window-body')) & Node.DOCUMENT_POSITION_FOLLOWING")!=0,'SkySynth preview is pinned above its scrollable controls')
    check(page.locator('#profilerChart').evaluate("e=>!!e.closest('.profiler-pin')"),'Profiler chart is in the pinned output header')
    # Lock behaviour: local LOCK blocks global change; panel UNLOCK overrides it without mutating local lock.
