    check(abs(page.evaluate('__XENOFIELD__.store.settings.freqX')+0.321)>1e-4 and page.evaluate("__XENOFIELD__.store.submenuLocks['skysynth-synth']") is True,'Panel UNLOCK overrides but preserves submenu lock state')
    check(page.locator('#hdriFile').get_attribute('accept').startswith('.exr,.hdr'),'HDRI picker advertises EXR/HDR first-class')
    # Preview can collapse and re-enable.
    page.evaluate("document.getElementById('envPreview').click()")
    check(page.locator('#previewWrap').get_attribute('class').find('preview-disabled')>=0,'Preview click collapses preview')
    check('CLICK TO ENABLE PREVIEW' in page.locator('#previewToggleText').inner_text(),'Collapsed preview presents enable affordance')
    page.evaluate("document.getElementById('previewToggleText').click()")
    check('preview-disabled' not in page.locator('#previewWrap').get_attribute('class'),'Preview can be re-enabled')
    # Local EXR import remains functional in CPU/browser test mode.
    page.locator('#hdriFile').set_input_files(str(root/'assets/calibration-panorama.exr'));page.wait_for_timeout(250)
    check(page.evaluate('__XENOFIELD__.hdriFrame?.type')=='exr','EXR publishes as HDRI input')
    check('local EXR' in page.evaluate('__XENOFIELD__.hdriFrame.metrics.decoder'),'Common EXR decodes locally')
    check(not errors,'No JavaScript page errors during bounded UI checks')
    check(page.evaluate('__XENOFIELD__.bridge.fallback===null'),'Embedded standalone worker starts without main-thread fallback')
    page.evaluate("__XENOFIELD__.store.set('envMode','plasma'); __XENOFIELD__.bridge.tick(performance.now(),__XENOFIELD__.store.settings,__XENOFIELD__.store.palettes[__XENOFIELD__.store.settings.lutSlot])");page.wait_for_timeout(250);check(page.evaluate("__XENOFIELD__.bridge.frames>0 && __XENOFIELD__.bridge.metrics?.backend==='Web Worker'"),'Embedded classic worker executes a SkySynth frame and returns it')
    # V4.4b: real DOM interactions with independent controls, ranges, presets, locks and persistence.
    page.evaluate("for(const key of Object.keys(__XENOFIELD__.store.submenuLocks))__XENOFIELD__.store.setSubmenuLock(key,false);for(const key of Object.keys(__XENOFIELD__.store.panelGlobalLocks))__XENOFIELD__.store.setPanelGlobalLock(key,'none');document.getElementById('notification').classList.add('hidden')")
