    check(page.locator('#kineticDock').is_visible(),'Kinetic dock opens from the workspace toolbar')
    check(page.locator('[data-kinetic-tab]').count()==6,'Six kinetic module tabs are present')
    check(page.locator('#kineticDock .param').count()==94,'All 94 new numeric controls are in the validated range system')
    check(page.locator('#kineticDock .param label[data-tip]').count()==94,'All new numeric controls carry explanatory tooltips')
