    page.locator('#kineticDock .kinetic-tools select').select_option('VOXEL SPRAY')
    page.locator('#kineticDock .kinetic-tools button').filter(has_text='LOAD STACK').click()
    check(page.evaluate("__XENOFIELD__.store.settings.volumeEnabled && __XENOFIELD__.store.settings.volumeResolution==='24'"),'Loading Voxel Spray sets the actual volume module, not a disconnected UI preview')
    page.locator('[data-kinetic-tab=volume]').click()
    page.locator('[data-kinetic-page=volume] .kinetic-subtabs button').filter(has_text='CACHE').click()
    page.locator('#volumeDensityFPS').fill('0.1');page.locator('#volumeDensityFPS').press('Enter')
    check(page.evaluate('__XENOFIELD__.store.settings.volumeDensityFPS')==0.1,'Numeric cache cadence accepts its slow 0.1 Hz engineering limit')
    page.locator('[data-kinetic-tab=temporal]').click()
    page.locator('[data-kinetic-page=temporal] .kinetic-subtabs button').filter(has_text='FEEDBACK').click()
    page.locator('#feedbackPersistence').fill('0.99');page.locator('#feedbackPersistence').press('Enter')
    page.locator('#feedbackAmount').fill('0.2');page.locator('#feedbackAmount').press('Enter')
    page.locator('#feedbackBlend').select_option('add')
    check(page.evaluate("__XENOFIELD__.store.settings.feedbackPersistence===0.99&&__XENOFIELD__.store.settings.feedbackAmount===0.2&&__XENOFIELD__.store.settings.feedbackBlend==='add'"),'Feedback persistence, layer opacity and additive blend are independently editable')
    page.locator('[data-kinetic-tab=aa]').click()
    page.locator('#ssaaArea').select_option('2');page.locator('#msaa').select_option('4');page.locator('#textureFilter').select_option('manual32')
    check('MANUAL' in page.locator('#textureFilter option:checked').inner_text(),'AF32 is visibly labelled manual experimental')
    page.locator('[data-submenu-lock=kinetic-aa]').click()
    page.locator('#kineticDock .kinetic-tools select').select_option('ABSURD AA');page.locator('#kineticDock .kinetic-tools button').filter(has_text='LOAD STACK').click()
    check(page.evaluate("__XENOFIELD__.store.settings.ssaaArea==='2'&&__XENOFIELD__.store.settings.temporalSamples==='32'"),'AA module lock protects SSAA while independent temporal sample target can change')
    page.evaluate("__XENOFIELD__.store.setSubmenuLock('kinetic-aa',false);__XENOFIELD__.store.set('feedbackPersistence',0.973);__XENOFIELD__.store.savePanelPreset('temporal','UI roundtrip');globalThis.kineticSnapshot=__XENOFIELD__.store.snapshot();__XENOFIELD__.store.set('feedbackPersistence',0.1);__XENOFIELD__.store.applySnapshot(kineticSnapshot)")
    check(page.evaluate("__XENOFIELD__.store.settings.feedbackPersistence===0.973&&__XENOFIELD__.store.panelPresets.temporal['UI roundtrip'].settings.feedbackPersistence===0.973"),'Project snapshot round-trip retains new values and user module presets')
