    check(page.locator('#openProceduralClouds').count()==1,'Procedural Clouds has a dedicated workspace dock entry')
    page.locator('#openProceduralClouds').click();check(page.locator('#proceduralClouds').is_visible(),'Procedural Clouds panel opens independently of the kinetic dock')
